test('enum/ts5.0-const-foldable/input.ts', async () => {
  const source =
    '// ts 5.0 feature\n\nconst BaseValue = 10;\nconst Prefix = "/data";\nconst enum Values {\n  First = BaseValue, // 10\n  Second, // 11\n  Third, // 12\n}\n\nconst xxx = 100 + Values.First;\nconst yyy = xxx;\n\nconst enum Routes {\n  Parts = `${Prefix}/parts`, // "/data/parts"\n  Invoices = `${Prefix}/invoices`, // "/data/invoices"\n  x = `${Values.First}/x`,\n  y = `${yyy}/y`,\n}\n';
  expect(await transformOutcome(source, 'input.ts', { typescript: 'strip' }))
    .toMatchInlineSnapshot(`
    "// ts 5.0 feature
    const BaseValue = 10;
    const Prefix = '/data';
    var Values = /* @__PURE__ */ (function (Values) {
      Values[(Values['First'] = BaseValue)] = 'First';
      Values[(Values['Second'] = 1 + Values['First'])] = 'Second';
      Values[(Values['Third'] = 1 + Values['Second'])] = 'Third';
      return Values;
    })(Values || {});
    const xxx = 100 + Values.First;
    const yyy = xxx;
    var Routes = /* @__PURE__ */ (function (Routes) {
      Routes['Parts'] = \`\${Prefix}/parts\`;
      Routes['Invoices'] = \`\${Prefix}/invoices\`;
      Routes['x'] = \`\${Values.First}/x\`;
      Routes['y'] = \`\${yyy}/y\`;
      return Routes;
    })(Routes || {});"
  `);
});

